const fs = require('fs');

const data = fs.readFileSync(0, 'utf8').trim().split(/\s+/).map(Number);
const n = data[0];
const square = [];
let zeroRow = -1;
let zeroCol = -1;
let index = 1;

for (let r = 0; r < n; r++) {
  square[r] = data.slice(index, index + n);
  index += n;

  for (let c = 0; c < n; c++) {
    if (square[r][c] === 0) {
      zeroRow = r;
      zeroCol = c;
    }
  }
}

let magicSum = 0;
for (let r = 0; r < n; r++) {
  if (r !== zeroRow) {
    magicSum = square[r].reduce((sum, value) => sum + value, 0);
    break;
  }
}

const missingValue =
  magicSum - square[zeroRow].reduce((sum, value) => sum + value, 0);

console.log(`${missingValue}\n${zeroRow + 1}\n${zeroCol + 1}`);
